import type { Runtime } from "./tools.js";
import type { McpTool } from "./types.js";

/** Generate TypeScript argument interfaces for every tool. */
export function generateTypes(tools: McpTool[]): string {
  const lines: string[] = [
    "// Auto-generated by openapi-mcp-runtime — do not edit.",
    "",
  ];
  const names: string[] = [];
  for (const tool of tools) {
    const iface = `${pascal(tool.name)}Args`;
    names.push(tool.name);
    lines.push(`export interface ${iface} ${interfaceBody(tool.inputSchema)}`);
    lines.push("");
  }
  lines.push(`export type ToolName = ${names.length ? names.map((n) => JSON.stringify(n)).join(" | ") : "never"};`);
  lines.push("");
  return lines.join("\n");
}

/** Generate a self-contained TypeScript client for the spec. */
export function generateClient(runtime: Runtime): string {
  const types = generateTypes(runtime.tools);
  const entries = runtime.tools.map((tool) => {
    const params = tool.parameters ?? [];
    const path = params.filter((p) => p.in === "path").map((p) => p.name);
    const query = params.filter((p) => p.in === "query").map((p) => p.name);
    const header = params.filter((p) => p.in === "header").map((p) => p.name);
    return `  ${JSON.stringify(tool.name)}: {\n    method: ${JSON.stringify(tool.method)},\n    path: ${JSON.stringify(tool.path)},\n    params: { path: ${JSON.stringify(path)}, query: ${JSON.stringify(query)}, header: ${JSON.stringify(header)} },\n  },`;
  });

  return `${types}
const DEFAULT_BASE_URL = ${JSON.stringify(runtime.baseUrl)};

const TOOLS = {
${entries.join("\n")}
} as const;

export type GeneratedToolName = keyof typeof TOOLS;

export interface CallToolOptions {
  baseUrl?: string;
  headers?: Record<string, string>;
}

/** Call a generated tool. Returns the parsed JSON body, or the raw text. */
export async function callTool<T = unknown>(
  name: GeneratedToolName,
  args: Record<string, unknown> = {},
  options: CallToolOptions = {},
): Promise<T> {
  const spec = TOOLS[name];
  const base = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\\/+$/, "");

  let path = spec.path;
  for (const key of spec.params.path) {
    path = path.replace(\`{\${key}}\`, encodeURIComponent(String(args[key] ?? "")));
  }

  const query = new URLSearchParams();
  for (const key of spec.params.query) {
    const value = args[key];
    if (value == null) continue;
    if (Array.isArray(value)) value.forEach((item) => query.append(key, String(item)));
    else query.append(key, String(value));
  }

  const headers: Record<string, string> = { ...options.headers };
  for (const key of spec.params.header) {
    if (args[key] != null) headers[key] = String(args[key]);
  }

  const consumed = new Set([...spec.params.path, ...spec.params.query, ...spec.params.header]);
  const rest: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(args)) {
    if (!consumed.has(key) && value !== undefined) rest[key] = value;
  }

  const qs = query.toString();
  const res = await fetch(\`\${base}\${path}\${qs ? \`?\${qs}\` : ""}\`, {
    method: spec.method,
    headers,
    body: Object.keys(rest).length ? JSON.stringify(rest) : undefined,
  });
  const text = await res.text();
  try {
    return JSON.parse(text) as T;
  } catch {
    return text as unknown as T;
  }
}
`;
}

function interfaceBody(schema: any): string {
  if (!schema || typeof schema !== "object") return "{}";
  const properties = schema.properties ?? {};
  const required = new Set<string>(Array.isArray(schema.required) ? schema.required : []);
  const keys = Object.keys(properties);
  if (keys.length === 0) return "{}";
  const lines = keys.map((key) => {
    const optional = required.has(key) ? "" : "?";
    const safeKey = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key);
    return `  ${safeKey}${optional}: ${schemaToTs(properties[key])};`;
  });
  return `{\n${lines.join("\n")}\n}`;
}

function schemaToTs(schema: any): string {
  if (!schema || typeof schema !== "object") return "unknown";
  if (Array.isArray(schema.enum) && schema.enum.length) {
    return schema.enum.map((value: unknown) => JSON.stringify(value)).join(" | ");
  }
  let type = schema.type;
  if (Array.isArray(type)) {
    const parts = type.map((t: string) => schemaToTs({ ...schema, type: t }));
    return parts.join(" | ");
  }
  switch (type) {
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "string":
      return "string";
    case "array":
      return `Array<${schemaToTs(schema.items ?? {})}>`;
    case "object":
      return schema.properties ? interfaceBody(schema) : "Record<string, unknown>";
    case "null":
      return "null";
    default:
      return "unknown";
  }
}

function pascal(input: string): string {
  const parts = input.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  const joined = parts.map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join("");
  return /^[0-9]/.test(joined) ? `_${joined}` : joined || "Tool";
}
